@Module
@InstallIn(SingletonComponent::class)
object AppModule {
    @Provides @Singleton fun clock(): Clock = SystemClock()
    @Provides fun repo(db: Db): OrderRepository = SqlOrderRepository(db)
}

class OrderService @Inject constructor(
    private val repo: OrderRepository, private val clock: Clock)

@Component abstract class AppComponent {
    abstract val service: OrderService
    @Provides fun clock(): Clock = SystemClock()
}

@Inject class OrderService(
    private val repo: OrderRepository, private val clock: Clock)
